function projectFacts(project){const rows=[['მასალა',project.material],['სივრცე',project.space],['ქალაქი',project.city]].filter(([,value])=>realValue(value));return rows.length?`<dl class="project-facts">${rows.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`:'';}

function projectCards(){
return lithosProjects.map((project,index)=>{const photo=project.photos[0];return `<button class="project-card" data-project="${esc(project.id)}" aria-label="${esc(project.title)} — ${project.photos.length} ფოტო; გალერეის გახსნა"><div class="project-img"><img src="${esc(photo.thumbnail)}" width="${photo.thumbWidth}" height="${photo.thumbHeight}" style="object-position:${esc(project.position)}" alt="${esc(photo.alt)}" loading="lazy" decoding="async"><span class="circle-arrow" aria-hidden="true">→</span><span class="project-photo-count">${project.photos.length} ფოტო</span></div><div class="project-caption"><div><h3>${esc(project.title)}</h3><p>${esc(project.subtitle)}</p>${projectFacts(project)}</div><span>${String(index+1).padStart(2,'0')}</span></div></button>`;}).join('');
}
